# Either AI Workspace - Windows Native 1-Line Installer & Launcher\r\n$Host.UI.RawUI.WindowTitle = 'Installing Either AI Workspace...'\r\nWrite-Host ''\r\nWrite-Host '  ================================================================' -ForegroundColor Magenta\r\nWrite-Host '    ✦ EITHER AI WORKSPACE — SOVEREIGN AUTONOMOUS AGENT OS ✦       ' -ForegroundColor Cyan\r\nWrite-Host '  ================================================================' -ForegroundColor Magenta\r\nWrite-Host ''\r\nWrite-Host '  [1/3] Connecting to Sovereign Cloud Infrastructure...' -ForegroundColor Yellow\r\n$cloudUrl = 'https://either-ai.vercel.app'\r\n$appUrl = 'https://either-ai.vercel.app/?app=1&desktop=1'\r\nWrite-Host '        Connected to: https://either-ai.vercel.app (Verified Cloud Server)' -ForegroundColor Green\r\n\r\nWrite-Host '  [2/3] Configuring Windows Native Desktop App and Taskbar Integration...' -ForegroundColor Yellow\r\n$appDir = Join-Path $env:LOCALAPPDATA 'EitherAIWorkspace'\r\nif (!(Test-Path $appDir)) {\r\n    New-Item -ItemType Directory -Path $appDir -Force | Out-Null\r\n}\r\n\r\n$iconFile = Join-Path $appDir 'icon.ico'\r\ntry {\r\n    Invoke-WebRequest -Uri 'https://either-ai.vercel.app/icons/icon.ico' -OutFile $iconFile -UseBasicParsing -TimeoutSec 10 -ErrorAction SilentlyContinue\r\n} catch {}\r\n\r\n$edgeCandidates = @(\r\n    'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe',\r\n    'C:\Program Files\Microsoft\Edge\Application\msedge.exe',\r\n    'C:\Program Files\Google\Chrome\Application\chrome.exe',\r\n    'C:\Program Files (x86)\Google\Chrome\Application\chrome.exe'\r\n)\r\n\r\n$targetExe = ''\r\nforeach ($cand in $edgeCandidates) {\r\n    if (Test-Path $cand) {\r\n        $targetExe = $cand\r\n        break\r\n    }\r\n}\r\n\r\n$desktopDir = [System.Environment]::GetFolderPath('Desktop')\r\n$shortcutPath = Join-Path $desktopDir 'Either AI Workspace.lnk'\r\n$wshShell = New-Object -ComObject WScript.Shell\r\n$shortcut = $wshShell.CreateShortcut($shortcutPath)\r\n\r\nif ($targetExe -ne '') {\r\n    $shortcut.TargetPath = $targetExe\r\n    $shortcut.Arguments = "--app=$appUrl"\r\n} else {\r\n    $shortcut.TargetPath = $appUrl\r\n}\r\n\r\nif (Test-Path $iconFile) {\r\n    $shortcut.IconLocation = "$iconFile,0"\r\n}\r\n$shortcut.Description = 'Either AI Workspace - Sovereign Autonomous Agent OS (Cloud Connected)'\r\n$shortcut.WorkingDirectory = $appDir\r\n$shortcut.Save()\r\n\r\nWrite-Host '  [3/3] Launching Either AI Desktop Application...' -ForegroundColor Yellow\r\nif ($targetExe -ne '') {\r\n    Start-Process $targetExe -ArgumentList "--app=$appUrl"\r\n} else {\r\n    Start-Process $appUrl\r\n}\r\n\r\nWrite-Host ''\r\nWrite-Host '  ================================================================' -ForegroundColor Green\r\nWrite-Host '    [OK] EITHER AI INSTALLED - RUNNING DIRECTLY ON OUR CLOUD SERVERS' -ForegroundColor Green\r\nWrite-Host '  ================================================================' -ForegroundColor Green\r\nWrite-Host '  * Zero local servers or terminal commands required.' -ForegroundColor Green\r\nWrite-Host "  * Desktop shortcut created at: $shortcutPath" -ForegroundColor Cyan\r\nWrite-Host ''